begin;create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api;set local search_path=extensions,pg_catalog;select no_plan();
create temporary table lifecycle_fixture(pack uuid,replacement uuid,reference uuid,programme uuid);grant select,insert,update on lifecycle_fixture to cuevo_api;
set local role cuevo_api;select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000001',true);
insert into lifecycle_fixture(pack)select(internal.configure_curriculum('version.create',null,'{"packId":"school-life-golden","kind":"school_custom","framework":"School Custom","programme":"School lifecycle","version":"school-1","scope":"school-synthetic","sourceStatus":"VERIFIED","rightsStatus":"PERMITTED","sourceLocation":"repo:school-authored","sourceChecksum":null,"synthetic":true,"reason":"School-authored technical case"}','lifecycle-pack',repeat('a',64),'lifecycle')->>'id')::uuid;
update lifecycle_fixture set reference=(internal.configure_curriculum('reference.create',null,jsonb_build_object('packVersionId',pack,'parentId',null,'type','objective','title','School explanation','description','School-authored checking objective','code',null,'sequence',1,'subjectId','43000000-0000-4000-8000-000000000001','yearGroupId','42000000-0000-4000-8000-000000000001'),'lifecycle-ref',repeat('b',64),'lifecycle')->>'id')::uuid;
select is(internal.read_curriculum_lifecycle((select pack from lifecycle_fixture),25,null)->>'state','DRAFT','New school source requires explicit review');
select throws_ok($$select internal.configure_curriculum('programme.create',null,jsonb_build_object('packVersionId',(select pack from lifecycle_fixture),'name','Unreviewed programme','classId','30000000-0000-4000-8000-000000000001','subjectId','43000000-0000-4000-8000-000000000001','yearGroupId','42000000-0000-4000-8000-000000000001','confirmConfiguration',true),'lifecycle-unreviewed-programme',repeat('c',64),'lifecycle')$$,'22023',null,'Unreviewed source cannot configure programme');
select lives_ok($$select internal.transition_curriculum_lifecycle((select pack from lifecycle_fixture),'{"state":"APPROVED","expectedRevision":1,"reviewBasis":"SCHOOL_AUTHORED","artifactDirectory":null,"replacementVersionId":null,"reason":"Human-reviewed school source","confirmTransition":true}',null,'lifecycle-approved',repeat('d',64),'lifecycle')$$,'Explicit school-authored approval is technical only');
select lives_ok($$select internal.transition_curriculum_lifecycle((select pack from lifecycle_fixture),'{"state":"ACTIVE","expectedRevision":2,"reviewBasis":"SCHOOL_AUTHORED","artifactDirectory":null,"replacementVersionId":null,"reason":"Human-reviewed school source activation","confirmTransition":true}',null,'lifecycle-active',repeat('e',64),'lifecycle')$$,'Reviewed source activates for school configuration');
select lives_ok($$select internal.transition_curriculum_lifecycle((select pack from lifecycle_fixture),'{"state":"ACTIVE","expectedRevision":2,"reviewBasis":"SCHOOL_AUTHORED","artifactDirectory":null,"replacementVersionId":null,"reason":"Human-reviewed school source activation","confirmTransition":true}',null,'lifecycle-active',repeat('e',64),'lifecycle')$$,'Original-key activation replay is exact');
select is(internal.read_curriculum_lifecycle((select pack from lifecycle_fixture),25,null)->>'customerReady','false','Technical activation never asserts customer-ready');
select throws_ok($$select internal.configure_curriculum('reference.create',null,jsonb_build_object('packVersionId',(select pack from lifecycle_fixture),'parentId',null,'type','objective','title','Late school addition','description','Cannot alter approved hierarchy','code',null,'sequence',2,'subjectId',null,'yearGroupId',null),'lifecycle-late-ref',repeat('f',64),'lifecycle')$$,'22023',null,'Reviewed hierarchy additions require a new draft source version');
update lifecycle_fixture set programme=(internal.configure_curriculum('programme.create',null,jsonb_build_object('packVersionId',pack,'name','Reviewed school programme','classId','30000000-0000-4000-8000-000000000001','subjectId','43000000-0000-4000-8000-000000000001','yearGroupId','42000000-0000-4000-8000-000000000001','confirmConfiguration',true),'lifecycle-programme',repeat('f',64),'lifecycle')->>'id')::uuid;
select lives_ok($$select internal.transition_curriculum_lifecycle((select pack from lifecycle_fixture),'{"state":"RETIRED","expectedRevision":3,"reviewBasis":"SCHOOL_AUTHORED","artifactDirectory":null,"replacementVersionId":null,"reason":"No course work uses this context","confirmTransition":true}',null,'lifecycle-retired',repeat('a',64),'lifecycle')$$,'Unused resolved source can retire');
select throws_ok($$select internal.configure_curriculum('programme.create',null,jsonb_build_object('packVersionId',(select pack from lifecycle_fixture),'name','Retired new programme','classId','30000000-0000-4000-8000-000000000001','subjectId','43000000-0000-4000-8000-000000000001','yearGroupId','42000000-0000-4000-8000-000000000001','confirmConfiguration',true),'lifecycle-retired-programme',repeat('b',64),'lifecycle')$$,'22023',null,'Retired source denies new programme configuration');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select throws_ok($$select internal.require_curriculum_academic_write('50000000-0000-4000-8000-000000000002')$$,'42501',null,'Private purpose write boundary denies foreign/unavailable course');
select throws_ok($$select internal.transition_curriculum_lifecycle((select pack from lifecycle_fixture),'{}',null,'lifecycle-teacher-denied',repeat('c',64),'lifecycle')$$,'42501',null,'Teacher cannot change lifecycle authority');
reset role;
select throws_ok($$update app.curriculum_lifecycle_revisions set reason='Rewrite'where version_id=(select pack from lifecycle_fixture)$$,'55000',null,'Lifecycle revisions immutable');
select ok(not has_table_privilege('cuevo_api','app.curriculum_lifecycle_revisions','SELECT')and not has_function_privilege('authenticated','internal.transition_curriculum_lifecycle(uuid,jsonb,jsonb,text,text,text)','EXECUTE'),'Lifecycle raw records and browser writes remain private');
select ok(not has_function_privilege('cuevo_api','internal.lock_academic_course(uuid,uuid)','EXECUTE')and has_function_privilege('cuevo_api','internal.require_curriculum_academic_write(uuid)','EXECUTE'),'Structural lock stays private while purpose write boundary is granted');
select*from finish();rollback;
